/************************************************************************************************************************
/*-------------------------------------------------- Validation Functions ------------------------------------------
************************************************************************************************************************/
/*
 * =========================================================================================================
 *
 * Add a coach validation error
 *
 * EX:	addError(tw.local.name , 'this is a control validation message!' , 'this is a validation message!');
 *
 * =========================================================================================================
 */
function addError(fieldName, controlMessage, validationMessage, fromMandatory) {
	tw.system.coachValidation.addValidationError(fieldName, controlMessage);
	fromMandatory && mandatoryTriggered ? "" : (tw.local.errorMessage += "<li>" + validationMessage + "</li>");
}
/*
 * =================================================================================================================================
 *
 * Add a coach validation error if the string length is less than given length
 *
 * EX:	minLength(tw.local.name , 'tw.local.name' , 10 , 'this is a control validation message!' , 'this is a validation message!')
 *
 * =================================================================================================================================
 */

function minLength(field, fieldName, len, controlMessage, validationMessage) {
	if (field != null && field != undefined && field.length < len) {
		addError(fieldName, controlMessage, validationMessage);
		return false;
	}
	return true;
}
/*
 * =======================================================================================================================
 *
 * Add a coach validation error if the string length is greater than given length
 *
 * EX:	maxLength(tw.local.name , 'tw.local.name' , 14 , 'this is a validation message!' , 'this is a validation message!')
 *
 * =======================================================================================================================
 */
function maxLength(field, fieldName, len, controlMessage, validationMessage) {
	if (field && field.length > len) {
		addError(fieldName, controlMessage, validationMessage);
		return false;
	}
	return true;
}
/*
 * ==================================================================================================================
 *
 * Add a coach validation error if the field is null 'Mandatory'
 *
 * EX:	notNull(tw.local.name , 'tw.local.name')
 *
 * ==================================================================================================================
 */

function mandatory(field, fieldName) {
	if (field == null || field == undefined) {
		addError(fieldName, tw.resource.ValidationMessages.ThisFieldIsMandatory, tw.resource.ValidationMessages.MandatoryFields, true);
		mandatoryTriggered = true;
		return false;
	} else {
		switch (typeof field) {
			case "string":
				if (field.trim() != undefined && field.trim() != null && field.trim().length == 0) {
					addError(fieldName, tw.resource.ValidationMessages.ThisFieldIsMandatory, tw.resource.ValidationMessages.MandatoryFields, true);
					mandatoryTriggered = true;
					return false;
				}
				break;
			case "number":
				if (field == 0.0) {
					addError(fieldName, tw.resource.ValidationMessages.ThisFieldIsMandatory, tw.resource.ValidationMessages.MandatoryFields, true);
					mandatoryTriggered = true;
					return false;
				}
				if (field < 0) {
					var msg = "Invalid Value, This field can not be negative value.";
					addError(fieldName, msg, msg, true);
					mandatoryTriggered = true;
					return false;
				}
				break;

			default:
				// VALIDATE DATE OBJECT
				if (field && field.getTime && isFinite(field.getTime())) {
				} else {
					addError(fieldName, tw.resource.ValidationMessages.ThisFieldIsMandatory, tw.resource.ValidationMessages.MandatoryFields, true);
					mandatoryTriggered = true;
					return false;
				}
		}
	}
	return true;
}
/*
 * ==============================================================================================================================
 *
 * Add a coach validation error if the fromDate bigger than toDate
 *
 * EX:	sumDates(fomDate , toDate , 'tw.local.date' , 'this is a control validation message!' , 'this is a validation message!')
 *
 * =============================================================================================================================
 */

function sumDates(fromDate, toDate, fieldName, controlMessage, validationMessage) {
	if (toDate - fromDate == 0) {
		return true;
	}
	addError(fieldName, controlMessage, validationMessage);
	return false;
}

//=================================================================================
function checkNegativeValue(field, fieldName) {
	if (field < 0) {
		var msg = "Invalid Value, This field can not be negative value.";
		addError(fieldName, msg, msg, true);
		mandatoryTriggered = true;
		return false;
	}
	return true;
}
//=================================================================================
//Validate Decimal(10,6)
function validateDecimal(field, fieldName, controlMessage, validationMessage) {
	// Regular expression pattern for decimal validation
	var decimalPattern = /^\d{1,4}(\.\d{1,6})?$/;

	// Check if the decimal matches the pattern
	if (!decimalPattern.test(field)) {
		// Decimal is valid
		addError(fieldName, controlMessage, controlMessage);
		return false;
	} else {
		// Decimal is invalid
		return true;
	}
}
//========================================================================================
function validateTab(index, tabName) {
	if (tw.system.coachValidation.validationErrors.length > tempLength) {
		if (tw.local.errorMessage.length == 0) {
			tw.local.errorMessage += "<p>" + "Please complete fields in the following tabs:" + "</p>";
		}
		tw.local.errorMessage += "<li>" + tabName + "</li>";
		tempLength = tw.system.coachValidation.validationErrors.length;
		tw.local.invalidTabs[tw.local.invalidTabs.length] = index;
	}
}
//==============================================================
//Validate Decimal(14,2)
function validateDecimal2(field, fieldName, controlMessage, validationMessage) {
	// Regular expression pattern for decimal validation
	var decimalPattern = /^\d{1,12}(\.\d{1,2})?$/;

	// Check if the decimal matches the pattern
	if (!decimalPattern.test(field)) {
		// Decimal is valid
		addError(fieldName, controlMessage, controlMessage);
		return false;
	} else {
		// Decimal is invalid
		return true;
	}
}

function notPastDate(date, fieldName, controlMessage, validationMessage, exclude) {
	if (exclude) {
		if (date != null && date <= new Date()) {
			addError(fieldName, controlMessage, validationMessage);
			return false;
		}
		return true;
	} else {
		var today = new Date();
		today.setHours(0, 0, 0, 0);
		if (date != null && date < today) {
			addError(fieldName, controlMessage, validationMessage);
			return false;
		}
		return true;
	}
}
