///////////////////////////////
if(tw.local.odcRequest.requestNature.value == "update"){
	tw.local.parentRequestNoVIS = "READONLY";

}	
else{
	tw.local.parentRequestNoVIS = "None";
	
}	


if(tw.local.odcRequest.requestType.value == tw.epv.RequestType.Create ||tw.local.odcRequest.BasicDetails.requestType == tw.epv.RequestType.Recreate || tw.local.odcRequest.BasicDetails.requestType == tw.epv.RequestType.Amendment){
	tw.local.contractStageVIS = "READONLY";
}
else{
tw.local.contractStageVIS = "NONE";
}
/*Document Generation Section*/
///////////////////////////////
if(tw.local.odcRequest.requestType.value == tw.epv.RequestType.Amendment || tw.local.odcRequest.requestType.value == tw.epv.RequestType.Recreate){
	tw.local.requestTypeVIS = "EDITABLE";
}
else{
	tw.local.requestTypeVIS = "NONE";	
}
//if(tw.local.isFirstTime == true)
//{
//tw.local.odcRequest.GeneratedDocumentInfo.customerName = tw.local.odcRequest.CustomerInfo.customerName;
//}

tw.local.invoiceBillExist=0;

if(tw.local.odcRequest.requestType.value == tw.epv.RequestType.Amendment){
		tw.local.currencyListVIS = "READONLY";
		tw.local.advancedVis = "READONLY";
}
else{
	tw.local.currencyListVIS = "Editable";
	tw.local.advancedVis = "Editable";
}
