ns16:extensionElements.ns2:preAssignmentScript:
tw.local.activityName = "ACT01";
tw.local.requestAmend = tw.epv.RequestType.Amendment+"";
tw.local.requestRecreate = tw.epv.RequestType.Recreate+"";
tw.local.requestCreate = "" + tw.epv.RequestType.Create;
if(tw.local.odcRequest.requestType.value == tw.local.requestAmend || tw.local.odcRequest.requestType.value == tw.local.requestRecreate )
{
	tw.local.requestTypeVIS = "Editable";

}
else
{
	tw.local.requestTypeVIS = "None";
}

tw.local.paymentTerms = tw.epv.TermsAndConditions.paymentTerms;
tw.local.deliveryterms = tw.epv.TermsAndConditions.deliveryTerms;
tw.local.specialInstructions = tw.epv.TermsAndConditions.specialInstructions;
tw.local.instructions = tw.epv.TermsAndConditions.instructions;

if(tw.local.documentGenerated == true){
	tw.local.remittanceLetterListVIS = "EDITABLE";
}
else{
	tw.local.remittanceLetterListVIS = "NONE";
}

tw.local.disable = false;
console.log(tw.local.errorVis);

ns16:scriptTask.ns16:script:
tw.local.errorMessage = "";
var mandatoryTriggered = false;
// var choice = false;
var tempLength = 0;
tw.local.invalidTabs = [];
tw.system.coachValidation.validationErrors = [];
tw.system.coachValidation.clearValidationErrors();

/************************************************************************************************************************
/*-------------------------------------------------- All Section's Validation ------------------------------------------
************************************************************************************************************************/
//debugger;
//-------------------------------------------------DC TEMPLATE VALIDATION -------------------------------------------
mandatory(tw.local.odcRequest.stepLog.action, "tw.local.odcRequest.stepLog.action");
maxLength(tw.local.odcRequest.stepLog.comment, "tw.local.odcRequest.stepLog.comment", 500, "Shouldn't be more than 500 character", " Comment :" + "Shouldn't be more than 500 character");

if (tw.local.odcRequest.stepLog.action == tw.epv.CreationActions.cancelRequest) {
	mandatory(tw.local.odcRequest.stepLog.comment, "tw.local.odcRequest.stepLog.comment");
}
//	maxLength(tw.local.odcRequest.stepLog.comment , "tw.local.odcRequest.stepLog.comment",500 , "Shouldn't be more than 500 character" , " Comment :" + "Shouldn't be more than 500 character" );

if (tw.local.odcRequest.stepLog.action == tw.epv.CreationActions.submitRequest || tw.local.odcRequest.stepLog.action == tw.epv.CreationActions.submitRequestToHubDirectly) {
	//-------------------------------------------------BASIC DETAILS VALIDATION -----------------------------------------
	mandatory(tw.local.odcRequest.BasicDetails.exportPurpose.name, "tw.local.odcRequest.BasicDetails.exportPurpose");
	mandatory(tw.local.odcRequest.BasicDetails.paymentTerms.name, "tw.local.odcRequest.BasicDetails.paymentTerms");
	mandatory(tw.local.odcRequest.BasicDetails.productCategory.name, "tw.local.odcRequest.BasicDetails.productCategory");
	mandatory(tw.local.odcRequest.BasicDetails.commodityDescription, "tw.local.odcRequest.BasicDetails.commodityDescription");

	//debugger;

	if (tw.local.odcRequest.BasicDetails.Invoice.length == 0) {
//		tw.local.errorMessage += "<li>" + "Fill in at least one entry in invoices" + "</li>";
		tw.system.coachValidation.addValidationError("tw.local.invoiceBillExist", "Fill in at least one entry in invoices");
	} else {
		for (var i = 0; i < tw.local.odcRequest.BasicDetails.Invoice.length; i++) {
			mandatory(tw.local.odcRequest.BasicDetails.Invoice[i].invoiceDate, "tw.local.odcRequest.BasicDetails.Invoice[" + i + "].invoiceDate");
			mandatory(tw.local.odcRequest.BasicDetails.Invoice[i].invoiceNo, "tw.local.odcRequest.BasicDetails.Invoice[" + i + "].invoiceNo");
			maxLength(tw.local.odcRequest.BasicDetails.Invoice[i].invoiceNo, "tw.local.odcRequest.BasicDetails.Invoice[" + i + "].invoiceNo", 20, "Shouldn't be more than 20 character", "invoice Number: " + "Shouldn't be more than 20 character");
		}
	}
	if (tw.local.odcRequest.BasicDetails.Bills.length == 0) {
//		tw.local.errorMessage += "<li>" + "Fill in at least one entry in Bills" + "</li>";
		tw.system.coachValidation.addValidationError("tw.local.invoiceBillExist", "Fill in at least one entry in Bills");
	} else {
		for (var i = 0; i < tw.local.odcRequest.BasicDetails.Bills.length; i++) {
			mandatory(tw.local.odcRequest.BasicDetails.Bills[i].billOfLadingDate, "tw.local.odcRequest.BasicDetails.Bills[" + i + "].billOfLadingDate");
			mandatory(tw.local.odcRequest.BasicDetails.Bills[i].billOfLadingRef, "tw.local.odcRequest.BasicDetails.Bills[" + i + "].billOfLadingRef");
			maxLength(tw.local.odcRequest.BasicDetails.Bills[i].billOfLadingRef, "tw.local.odcRequest.BasicDetails.Bills[" + i + "].billOfLadingRef", 20, "Shouldn't be more than 20 character", "Bill Of lading Ref : " + "Shouldn't be more than 20 character");
		}
	}
	mandatory(tw.local.odcRequest.BasicDetails.CountryOfOrigin.name, "tw.local.odcRequest.BasicDetails.CountryOfOrigin");
	maxLength(tw.local.odcRequest.BasicDetails.flexCubeContractNo, "tw.local.odcRequest.BasicDetails.flexCubeContractNo", 16, tw.resource.ValidationMessages.MaxLength16, "Flex Cube Contract Number: " + tw.resource.ValidationMessages.MaxLength16);
	maxLength(tw.local.odcRequest.BasicDetails.commodityDescription, "tw.local.odcRequest.BasicDetails.commodityDescription", 160, "Shouldn't be more than 160 character", "Commodity Description: " + "Shouldn't be more than 160 character");

	if (tw.local.billsExist == true) {
		for (var i = 0; i < tw.local.odcRequest.BasicDetails.Bills.length; i++) {
